from pathlib import Path
from dataclasses import asdict
import json
from green.application.input_quality import require_complete_geometry
from green.infrastructure.cad.reader import EzdxfSceneReader
from green.application.errors import InputError
results=[]
for p in sorted(Path("out/real-input-survey").rglob("*.dxf")):
    try:
        scene = EzdxfSceneReader().read(p)
        result={"file":p.name, "gaps":[asdict(x) for x in scene.read_diagnostics.geometry_gaps], "unresolved_xrefs":scene.read_diagnostics.unresolved_xrefs}
        try:
            require_complete_geometry(scene)
            result["complete"]=True
        except InputError as error:
            result["complete"]=False
            result["error"]=str(error)
    except InputError as error:
        result={"file":p.name, "complete":False, "load_error":str(error)}
    results.append(result)
Path("docs/research/verified-pipeline/real_input_gaps.json").write_text(json.dumps(results, ensure_ascii=False, indent=2)+"\n")
print(json.dumps([{"file":r["file"],"complete":r["complete"],"gap_groups":len(r.get("gaps",[])),"load_error":r.get("load_error")} for r in results], ensure_ascii=False))
